//! Unit `data-starter-hulls`: the six starter hulls and the tutorial's 22 m variants (DESIGN.md L142-151,
//! L162-176, L252-275, L705, L801-822, L866-875).
//!
//! The committed files under `blueprints/starters/` and `blueprints/tutorial/` are generated by
//! [`starters::ships`], which drives the content crate's own loft, voxelizer, kit transform and canonical
//! writer. Regenerate them with
//! `BP_WRITE_STARTERS=1 cargo test -p content --test starter_hulls committed_files_match_the_generator`.
//! Every run regenerates them in memory and fails if a committed file differs, so a change to the voxelizer,
//! the kits, the materials or the paint tokens that moves a starter shows up here instead of silently.
//!
//! Every hull is checked as the game will see it: loaded from the embedded stock files through the real
//! loader, validated under the campaign and lobby rulesets at its act's cap, and floated with the generator's
//! cell-exact flat-water hydrostatics. The binding stability and seakeeping checks (the Float gauge's GM band,
//! heel, trim, propeller immersion, running straight, a Beaufort 7 beam sea, light load) sail the same files
//! through the editor's gauges and the simulation, on its 2 m buoyancy blocks (L650): see
//! `crates/sim-systems/tests/starter_hulls_sim.rs`.
mod starters;

use content::blueprint::io::{load_blueprint_with, to_file_text};
use content::blueprint::Blueprint;
use content::catalogue::Catalogue;
use content::cell::{CellGrid, Material};
use content::enums::{Act, Phase};
use content::ids::KitId;
use content::part::weapons::MunitionKind;
use content::part::{PartFunction, PartTag, PropulsorKind};
use content::ruleset::{Ruleset, RulesetKind};
use content::validate::{validate_blueprint, Issue, ValidationContext};
use std::collections::{BTreeMap, BTreeSet};

fn cat() -> Catalogue { Catalogue::load_embedded().expect("embedded catalogue loads") }

/// The six starters, the act that first offers each (L144-149), and the tutorial variants.
const STARTERS: [(&str, Act); 6] = [
    ("starters/patrol15.bp.ron", Act::Act1),
    ("starters/fac22.bp.ron", Act::Act1),
    ("starters/insertion26.bp.ron", Act::Act1),
    ("starters/corvette40.bp.ron", Act::Act2),
    ("starters/corvette60.bp.ron", Act::Act3),
    ("starters/destroyer90.bp.ron", Act::Act4),
];
const TUTORIAL: [&str; 4] = ["tutorial/fac22_tutorial.bp.ron", "tutorial/fac22_tutorial_float.bp.ron", "tutorial/fac22_tutorial_drive.bp.ron", "tutorial/fac22_tutorial_nogun.bp.ron"];

/// A committed stock file, loaded the way the game loads it.
fn stock(path: &str, c: &Catalogue) -> Blueprint {
    let (file, text) = content::data::stock_blueprint_files().find(|(p, _)| *p == path).unwrap_or_else(|| panic!("{path} is not committed"));
    load_blueprint_with(text, file, c).unwrap_or_else(|e| panic!("{path}: {e}")).blueprint
}

fn kits(bp: &Blueprint) -> BTreeSet<&str> { bp.kits.iter().map(|k| k.kit.as_str()).collect() }

fn parts(bp: &Blueprint) -> BTreeMap<String, usize> {
    let mut out = BTreeMap::new();
    for p in &bp.parts {
        *out.entry(p.part.to_string()).or_insert(0) += 1;
    }
    out
}

fn has(bp: &Blueprint, c: &Catalogue, f: impl Fn(&PartFunction) -> bool) -> bool { bp.parts.iter().any(|p| f(&c.part(&p.part).unwrap().function)) }

#[test]
fn committed_files_match_the_generator() {
    let c = cat();
    let write = std::env::var_os("BP_WRITE_STARTERS").is_some();
    let root = concat!(env!("CARGO_MANIFEST_DIR"), "/../../blueprints");
    let generated = starters::ships::all(&c);
    let paths: BTreeSet<&str> = generated.iter().map(|s| s.path).collect();
    let expected: BTreeSet<&str> = STARTERS.iter().map(|s| s.0).chain(TUTORIAL).collect();
    assert_eq!(paths, expected, "the generator writes exactly the six starters and the four tutorial hulls");
    let mut stale = Vec::new();
    for s in &generated {
        let text = to_file_text(&s.bp);
        let path = format!("{root}/{}", s.path);
        if write {
            std::fs::create_dir_all(std::path::Path::new(&path).parent().unwrap()).unwrap();
            std::fs::write(&path, &text).unwrap();
        } else {
            // Git may check the files out with CRLF line endings on Windows.
            let committed = std::fs::read_to_string(&path).unwrap_or_default().replace("\r\n", "\n");
            if committed != text {
                stale.push(s.path);
            }
            // Loading and saving again changes nothing, so opening a starter in the editor leaves no diff.
            let loaded = load_blueprint_with(&committed, s.path, &c).unwrap_or_else(|e| panic!("{}: {e}", s.path)).blueprint;
            assert_eq!(to_file_text(&loaded), committed, "{} does not round-trip", s.path);
        }
    }
    assert!(stale.is_empty(), "{stale:?} differ from the generator; regenerate with BP_WRITE_STARTERS=1 cargo test -p content --test starter_hulls");
}

#[test]
fn starters_are_afloat_fitted_and_legal() {
    let c = cat();
    for (path, act) in STARTERS {
        let bp = stock(path, &c);
        let cap = act.hull_cap_t();
        // Legal in the campaign from the act that offers it, and in a lobby at that act's cap (sandbox, skirmish
        // and PvP offer all six, L142).
        let check = |rules: &Ruleset| validate_blueprint(&bp, &c, &ValidationContext { ruleset: rules, available: None, enemy_class: false, complexity: None }).issues;
        for rules in [Ruleset::campaign(act), Ruleset { kind: RulesetKind::Open, tonnage_cap_t: cap, ..Ruleset::default() }] {
            let issues = check(&rules);
            assert!(issues.is_empty(), "{path} under {:?}: {issues:?}", rules.kind);
        }
        // The standard lobby ruleset's copy limits refuse only the second mine rail of the 60 m corvette, whose
        // brief is "mine rails" (L147) while the standard limit is one rail per hull; nothing else.
        for issue in check(&Ruleset { tonnage_cap_t: cap, ..Ruleset::default() }) {
            let rail = matches!(&issue, Issue::PartOverLimit { part, count: 2, limit: 1 } if part.as_str() == "rail.mine");
            assert!(rail && path == "starters/corvette60.bp.ron", "{path} under the standard ruleset: {issue:?}");
        }
        let stats = content::stats::compute_stats(&bp, &c);
        // Under the act's cap with room to grow (CI fails any starter over its cap, L151).
        assert!(stats.tonnage_t <= 0.9 * cap, "{path}: {:.1} t against the {cap} t cap", stats.tonnage_t);
        // Every compartment sealed: no open part leaves a hull space open to the sea or the sky (the simulation
        // counts an open compartment as outside the hull).
        let open = starters::open_cells(&bp, &c);
        assert!(open.is_empty(), "{path}: {} cells open to the outside, first {:?}", open.len(), open.first());
        // Afloat on its design waterline, upright with margin in the cell-exact model, no list and little trim.
        // The Float gauge's Pass band (L166) is held on the simulation's own buoyancy blocks in sim-systems.
        let h = starters::hydrostatics(&bp, &c);
        assert!(h.level_m.is_finite() && h.reserve > 1.0, "{path}: reserve buoyancy {:.2}", h.reserve);
        assert_eq!(h.row, bp.hull.design_waterline_y, "{path}: the design waterline is the equilibrium row");
        assert!(h.gm_over_beam >= 0.02, "{path}: GM {:.2} m is {:.1}% of beam", h.gm, h.gm_over_beam * 100.0);
        assert!(h.heel_deg.abs() <= 0.6, "{path}: lists {:.2} deg", h.heel_deg);
        assert!(h.trim_deg.abs() <= 1.2, "{path}: trims {:.2} deg", h.trim_deg);
        // Fitted: no part buried in plating, power to spare, propulsors for the engines, steering, a crew, a
        // bridge and a gun.
        assert!(starters::buried_parts(&bp, &c).is_empty(), "{path}: {:?}", starters::buried_parts(&bp, &c));
        let (supply, draw) = starters::power(&bp, &c);
        assert!(supply >= 1.2 * draw, "{path}: {supply} kW for {draw} kW");
        let (shaft, absorb) = starters::drive(&bp, &c);
        assert!(shaft > 0.0 && absorb >= 0.8 * shaft, "{path}: {shaft} kW of engines on {absorb} kW of propulsors");
        let steers = has(&bp, &c, |f| match f {
            PartFunction::Rudder { .. } => true,
            PartFunction::Propulsor(d) => d.steer_max_deg > 0.0,
            _ => false,
        });
        assert!(steers, "{path} cannot steer");
        // Propellers run fully immersed, tips a quarter metre under the design waterline.
        for p in &bp.parts {
            let def = c.part(&p.part).unwrap();
            if matches!(&def.function, PartFunction::Propulsor(d) if d.kind == PropulsorKind::Propeller) {
                let top = (p.pos.y as f64 + content::kit::rotated_size(def.size, p.rot)[1] as f64) * content::cell::CELL_M;
                assert!(top <= h.level_m - 0.25, "{path}: a propeller at {:?} reaches {top} m, the waterline is at {:.2} m", p.pos, h.level_m);
            }
        }
        assert!(stats.berths >= 4, "{path}: {} berths", stats.berths);
        assert!(has(&bp, &c, |f| matches!(f, PartFunction::Console)), "{path}: no bridge");
        assert!(has(&bp, &c, |f| matches!(f, PartFunction::Gun(_))), "{path}: no gun");
        for p in &bp.parts {
            assert!(c.part(&p.part).unwrap().phase <= Phase::R010, "{path}: {} is not in the first release", p.part);
        }
        // Stock data: CC BY 4.0 and a translation key for the name.
        assert_eq!(bp.header.licence, "CC-BY-4.0");
        let stem = path.trim_start_matches("starters/").trim_end_matches(".bp.ron");
        assert_eq!(bp.header.name_key.as_ref().map(|k| k.as_str()), Some(format!("starter.{stem}.name").as_str()), "{path}");
    }
}

#[test]
fn each_starter_answers_its_brief() {
    let c = cat();
    let tagged = |bp: &Blueprint, t: PartTag| bp.parts.iter().any(|p| c.part(&p.part).unwrap().tags.contains(&t));
    let munitions = |bp: &Blueprint, kind: MunitionKind| -> u32 {
        bp.parts
            .iter()
            .map(|p| match &c.part(&p.part).unwrap().function {
                PartFunction::Launcher(l) if c.munition(&l.munition).is_some_and(|m| m.kind == kind) => l.cells as u32,
                _ => 0,
            })
            .sum()
    };
    // The first starter a player meets carries the tutorial's four kits (L256) and the spec's 8 berths (L705),
    // from vertical-slice parts only, with margin for armour under 150 t.
    let fac = stock("starters/fac22.bp.ron", &c);
    for k in ["kit.gun", "kit.radar_mast", "kit.engine", "kit.fuel_tank"] {
        assert!(kits(&fac).contains(k), "fac22 lacks {k}");
    }
    let fs = content::stats::compute_stats(&fac, &c);
    assert_eq!(fs.berths, 8);
    assert!(fs.tonnage_t <= 135.0, "fac22: {:.1} t", fs.tonnage_t);
    assert!(fac.parts.iter().all(|p| c.part(&p.part).unwrap().phase == Phase::Slice), "fac22 uses only vertical-slice parts");
    // The insertion craft answers the stealth-insertion tag without a redesign (L151): composite wherever radar
    // can see it (every structure cell from the design waterline up, glazing aside), the low-signature mast, a
    // boat for the team and berths for it. Its worst radar aspect is checked in sim-systems.
    let ins = stock("starters/insertion26.bp.ron", &c);
    let g = CellGrid::from_rows(&ins.cells);
    let wl = ins.hull.design_waterline_y;
    let topsides: Vec<Material> = (0..g.len()).map(|i| (g.pos(content::ids::CellIndex(i as u32)), g.cells[i])).filter(|(p, c)| p.y >= wl && !c.is_empty() && c.material != Material::Glass).map(|(_, c)| c.material).collect();
    assert!(!topsides.is_empty() && topsides.iter().all(|&m| m == Material::Composite), "insertion26: topsides not all composite");
    assert!(kits(&ins).contains("kit.radar_mast.stealth") && tagged(&ins, PartTag::LowSignature));
    assert!(tagged(&ins, PartTag::RhibDavit) && tagged(&ins, PartTag::PassengerBerths));
    // The missile corvette's missiles; the 60 m corvette's mine rails and boarding kit (L147) and sonar for the
    // Act 3 submarines; the destroyer's area air defence and 24 berths (L705).
    let k40 = stock("starters/corvette40.bp.ron", &c);
    assert!(munitions(&k40, MunitionKind::AntiShipMissile) >= 8);
    let k60 = stock("starters/corvette60.bp.ron", &c);
    assert!(tagged(&k60, PartTag::MineRail) && tagged(&k60, PartTag::BoardingKit));
    assert!(has(&k60, &c, |f| matches!(f, PartFunction::Sensor(s) if s.kind == content::part::SensorKind::PassiveSonar)));
    let d90 = stock("starters/destroyer90.bp.ron", &c);
    assert_eq!(content::stats::compute_stats(&d90, &c).berths, 24);
    assert!(munitions(&d90, MunitionKind::Sam) >= 16);
    // Each act's starters are bigger than the last act's.
    let mut by_act: BTreeMap<u8, (f64, f64)> = BTreeMap::new();
    for (p, act) in STARTERS {
        let t = content::stats::compute_stats(&stock(p, &c), &c).tonnage_t;
        let e = by_act.entry(act.number()).or_insert((f64::MAX, 0.0));
        *e = (e.0.min(t), e.1.max(t));
    }
    let acts: Vec<(f64, f64)> = by_act.into_values().collect();
    assert!(acts.windows(2).all(|w| w[0].1 < w[1].0), "{acts:?}");
}

#[test]
fn tutorial_hulls_stage_the_first_ten_minutes() {
    let c = cat();
    let st = &c.tuning.stability;
    let fac = stock("starters/fac22.bp.ron", &c);
    let lesson = ["kit.gun", "kit.radar_mast", "kit.engine", "kit.fuel_tank"];
    // (path, tutorial kits already fitted, Float at Pass)
    let cases: [(&str, &[&str], bool); 4] = [
        (TUTORIAL[0], &[], false),
        (TUTORIAL[1], &[], true),
        (TUTORIAL[2], &["kit.engine", "kit.fuel_tank"], true),
        (TUTORIAL[3], &["kit.radar_mast", "kit.engine", "kit.fuel_tank"], true),
    ];
    for (path, fitted, pass) in cases {
        let bp = stock(path, &c);
        let r = validate_blueprint(&bp, &c, &ValidationContext { ruleset: &Ruleset::campaign(Act::Act1), available: None, enemy_class: false, complexity: None });
        assert!(r.is_ok(), "{path}: {:?}", r.issues);
        assert!(bp.parts.iter().all(|p| c.part(&p.part).unwrap().phase == Phase::Slice), "{path}: vertical-slice parts only");
        let have = kits(&bp);
        for k in lesson {
            assert_eq!(have.contains(k), fitted.contains(&k), "{path}: {k}");
        }
        assert!(starters::buried_parts(&bp, &c).is_empty(), "{path}");
        assert!(starters::open_cells(&bp, &c).is_empty(), "{path}: a compartment is open to the outside");
        assert_eq!(bp.header.name_key, fac.header.name_key, "{path}");
        // Afloat in every variant; the level-0 hull is under-beamed, so Float fails until the beam step (L256).
        let h = starters::hydrostatics(&bp, &c);
        assert!(h.level_m.is_finite() && h.reserve > 1.0, "{path} floats");
        assert_eq!(h.row, bp.hull.design_waterline_y, "{path}");
        if pass {
            assert!((st.gm_caution_low..=st.gm_caution_high).contains(&h.gm_over_beam), "{path}: GM {:.1}% of beam", h.gm_over_beam * 100.0);
        } else {
            assert!(h.gm <= 0.0, "{path}: GM {:.2} m must fail", h.gm);
        }
        // Without its engines and fuel the craft sits by the stern; nothing the lesson's kits do not fix.
        assert!(h.trim_deg.abs() <= 4.5, "{path}: trims {:.2} deg", h.trim_deg);
    }
    // Only the beam changes from level 0 to level 1, and the level-4 craft is the reward minus its gun kit.
    let (level0, level1) = (stock(TUTORIAL[0], &c), stock(TUTORIAL[1], &c));
    assert_eq!(parts(&level0), parts(&level1));
    let beam = |bp: &Blueprint| match &bp.hull.source {
        content::hull::HullSource::Lofted(s) => s.stations.iter().map(|s| s.beam_m).fold(0.0, f64::max),
        content::hull::HullSource::Freeform => panic!("the tutorial drags the beam handle of a lofted hull"),
    };
    assert!(beam(&level0) < beam(&level1) && beam(&level1) < beam(&fac));
    let nogun = stock(TUTORIAL[3], &c);
    let mut want = parts(&fac);
    for kp in &c.kit(&KitId::new("kit.gun")).unwrap().parts {
        *want.get_mut(kp.part.as_str()).unwrap() -= 1;
    }
    want.retain(|_, n| *n > 0);
    assert_eq!(parts(&nogun), want, "level 4 is the fitted craft without its gun kit");
    assert_eq!(nogun.hull, fac.hull);
}

/// Every starter name has an English row (the copy lint's coverage rule), and it is the file's own name.
#[test]
fn starter_names_have_english_text() {
    let c = cat();
    let csv = std::fs::read_to_string(concat!(env!("CARGO_MANIFEST_DIR"), "/../../game/i18n/starters.csv")).unwrap();
    let rows: BTreeMap<&str, &str> = csv.lines().skip(1).filter_map(|l| l.split_once(',')).collect();
    for path in STARTERS.iter().map(|s| s.0).chain(TUTORIAL) {
        let bp = stock(path, &c);
        let key = bp.header.name_key.clone().unwrap();
        let row = rows.get(key.as_str()).unwrap_or_else(|| panic!("no English row for {key}"));
        assert!(row.ends_with(&format!(",{}", bp.header.name)), "{key}: the English text is the file's name, {:?}", bp.header.name);
    }
}

/// Views of every generated hull for eyeballing a change: `cargo test -p content --test starter_hulls
/// print_designs -- --ignored --nocapture` (`BP_SECTION=<x>` picks the section column).
#[test]
#[ignore]
fn print_designs() {
    let c = cat();
    for s in starters::ships::all(&c) {
        eprintln!("{}\n{}\n{}", s.path, starters::summary(&s.bp, &c), starters::views(&s.bp, &c));
    }
}


